{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.Aureliolo/gdharness",
  "description": "A harness for driving a Godot 4 project from an agent: addons, runtime bridge, MCP server, CLI.",
  "repository": {
    "url": "https://github.com/Aureliolo/gdharness",
    "source": "github"
  },
  "websiteUrl": "https://github.com/Aureliolo/gdharness#readme",
  "version": "1.3.11",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "gdharness",
      "version": "1.3.11",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "name": "GODOT_PATH",
          "description": "Absolute path to the Godot 4.7 or newer executable. Without it, the usual install locations are searched.",
          "isRequired": false,
          "isSecret": false
        }
      ]
    }
  ]
}

{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.getsentry/sentry-mcp",
  "description": "MCP server for Sentry - error monitoring, issue tracking, and debugging for AI assistants",
  "repository": {
    "url": "https://github.com/getsentry/sentry-mcp",
    "source": "github",
    "subfolder": "packages/mcp-server"
  },
  "version": "0.40.0",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "@sentry/mcp-server",
      "version": "0.40.0",
      "transport": { "type": "stdio" },
      "environmentVariables": [
        {
          "description": "Your Sentry user authentication token",
          "isRequired": true,
          "format": "string",
          "isSecret": true,
          "name": "SENTRY_ACCESS_TOKEN"
        }
      ]
    }
  ],
  "remotes": [
    {
      "type": "streamable-http",
      "url": "https://mcp.sentry.dev/mcp"
    }
  ]
}

